import { mountTurnstile, clearTurnstile, turnstileToken } from './turnstile.js';
import { prepareGoogle, googleToken } from './google-auth.js';
import { dayKey, moveMonth, calendarDays, groupMatches } from './calendar.js';
import { mapLink, mapEmbed, invitation, newsText } from './match-utils.js';
import { t, lang, setLanguage, money, date } from './i18n.js';

const app=document.getElementById('app'),modal=document.getElementById('modal');
const state={data:null,admin:null,health:null,healthError:false,route:location.pathname,matchTab:'upcoming',calendarMonth:null,calendarDay:null,search:'',menu:false,statementPreview:null,auth:null,publicMatch:null};
const icons={home:'M3 10 12 3l9 7M5 9v11h5v-6h4v6h5V9',calendar:'M4 5h16v16H4zM7 3v4M17 3v4M4 10h16M8 14h2M14 14h2M8 17h2',wallet:'M3 6h17v15H3zM3 6V4h15v2M15 11h6v5h-6zM17 13.5h.1',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M19 8a3 3 0 0 1 0 6M20 17a3 3 0 0 1 2 3',news:'M4 3h16v18H4zM8 7h8M8 11h8M8 15h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',arrow:'M5 12h14M14 7l5 5-5 5',left:'M19 12H5M10 7l-5 5 5 5',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0M12 7a3 3 0 1 0 0 6 3 3 0 0 0 0-6',share:'M15 3h6v6M10 14 21 3M10 5H4v15h15v-6',close:'m6 6 12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14M15 15l6 6',logout:'M9 4H4v16h5M9 12h12M17 8l4 4-4 4',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',mail:'M3 5h18v14H3zM3 5l9 7 9-7',more:'M5 12h.1M12 12h.1M19 12h.1',ball:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m-3 6 3-2 3 2-1 4h-4zM9 9 5 7M15 9l4-2M14 13l3 5M10 13l-3 5',copy:'M8 8h13v13H8zM4 16H3V3h13v1',refresh:'M20 7V3l-4 4M20 7a9 9 0 1 0 1 8'};
const icon=name=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[name]||icons.ball}"/></svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=name=>name.split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();
const photoFor=uid=>state.data?.photos?.find(p=>p.user_id===uid)?.url||'';
const avatar=(name,yellow=false,photo='')=>`<span class="avatar ${yellow?'yellow':''}">${photo?`<img src="${esc(photo)}" alt="" loading="lazy">`:esc(initials(name))}</span>`;
const btn=(label,action,options={})=>`<button type="button" class="btn ${options.class||''}" data-action="${action}" ${options.id?`data-id="${esc(options.id)}"`:''} ${options.disabled?'disabled':''}>${options.icon?icon(options.icon):''}${esc(label)}</button>`;
const navLink=(path,label,ic,extra='')=>`<a href="${path}" data-nav="${path}" class="${extra}" >${ic?icon(ic):''}${esc(label)}</a>`;
const badge=(status,label)=>`<span class="badge ${['waitlist','offered','late_cancelled','queued','draft','pending'].includes(status)?'warn':['cancelled','absent','failed'].includes(status)?'danger':['expired','closed','excused'].includes(status)?'neutral':''}">${esc(label||t(status))}</span>`;
const localeDate=(value,options={},zone)=>date(value,options,zone||state.data?.settings?.timezone||'Europe/Vienna');
const longDate=(value,zone)=>localeDate(value,{weekday:'long',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'},zone);
const time=(value,zone)=>localeDate(value,{day:undefined,month:undefined,hour:'2-digit',minute:'2-digit'},zone);
const languageSelect=()=>`<select class="lang-select" data-language aria-label="${t('language')}"><option value="en" ${lang==='en'?'selected':''}>English</option><option value="de" ${lang==='de'?'selected':''}>Deutsch</option><option value="es" ${lang==='es'?'selected':''}>Español</option></select>`;
const brand=()=>`<a class="brand" href="/" data-nav="/"><img src="/assets/crest.png" alt="Breja FC"><span><strong>BREJA FC</strong><small>${t('tagline')}</small></span></a>`;
const admin=()=>state.data?.me?.role==='admin';
const developer=()=>state.data?.me?.role==='dev';
const manager=()=>admin()||developer();
const mine=m=>m.registrations.find(r=>r.mine&&!r.guest&&!['cancelled','expired'].includes(r.status));
const activeRegs=m=>m.registrations.filter(r=>r.status==='confirmed');
const currentMatches=()=>state.data.matches.filter(m=>m.status==='open'&&new Date(m.starts_at)>new Date()).sort((a,b)=>a.starts_at.localeCompare(b.starts_at));
const getMatch=mid=>state.data.matches.find(m=>m.id===mid);
const empty=(title,hint='',ic='ball')=>`<div class="empty">${icon(ic)}<h3>${esc(title)}</h3>${hint?`<p>${esc(hint)}</p>`:''}</div>`;
const heading=(title,subtitle,actions='',eyebrow='')=>`<div class="page-head"><div>${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h1>${esc(title)}</h1>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;
const field=(label,name,value='',options={})=>`<label class="field ${options.wide?'wide':''} ${options.mobileWide?'mobile-wide':''}"><span>${esc(label)}</span>${options.area?`<textarea name="${name}" ${options.required?'required':''} maxlength="${options.max||4000}">${esc(value)}</textarea>`:options.options?`<select name="${name}" ${options.required?'required':''}>${options.options.map(o=>`<option value="${esc(o.value)}" ${String(o.value)===String(value)?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`:`<input name="${name}" value="${esc(value)}" type="${options.type||'text'}" ${options.required?'required':''} ${options.readonly?'readonly':''} ${options.min!==undefined?`min="${options.min}"`:''} ${options.max!==undefined?`max="${options.max}"`:''} ${options.step?`step="${options.step}"`:''} ${options.placeholder?`placeholder="${esc(options.placeholder)}"`:''} ${options.autocomplete?`autocomplete="${options.autocomplete}"`:''} ${!['number','date','time','month'].includes(options.type)?`maxlength="${options.maxLength||300}"`:''}>`}${options.hint?`<small>${esc(options.hint)}</small>`:''}</label>`;
const check=(label,name,required=true,checked=false)=>`<label class="check"><input type="checkbox" name="${name}" ${required?'required':''} ${checked?'checked':''}><span>${esc(label)}</span></label>`;
const formActions=(label='save')=>`<div class="form-actions">${btn(t('cancel'),'dismiss',{class:'btn-ghost'})}<button class="btn btn-primary" type="submit">${icon('check')}${t(label)}</button></div>`;
const optionsMethods=()=>['cash','transfer','other'].map(value=>({value,label:t(value)}));
function notify(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=`<span>${esc(message)}</span><button aria-label="${t('close')}">${icon('close')}</button>`;el.querySelector('button').onclick=()=>el.remove();document.getElementById('notifications').append(el);setTimeout(()=>el.remove(),error?12000:4500);}
async function api(path,method='GET',data){let response;try{response=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json'},...(data!==undefined?{body:JSON.stringify(data)}:{})});}catch{throw new Error('network_error');}const result=await response.json();if(!response.ok){const error=new Error(result.error||'error');error.details=result.details;throw error;}return result;}
async function refresh(){state.data=await api('/bootstrap');state.admin=null;state.health=null;state.healthError=false;state.statementPreview=null;if(state.data.config.firebase)void prepareGoogle(state.data.config.firebase).catch(()=>{});if(state.data.me){if(!localStorage.getItem('breja-language'))setLanguage(state.data.me.language);if(admin()&&state.data.me.membership_status==='approved')state.admin=await api('/admin');if(developer()&&state.data.me.membership_status==='approved'){try{state.health=await api('/dev/health');}catch{state.healthError=true;}}}render();}
function navigate(path){state.route=path;state.menu=false;history.pushState({},'',path);render();window.scrollTo({top:0,behavior:'instant'});if(path==='/health'&&developer())void refresh().catch(()=>{state.health=null;state.healthError=true;render();});}
window.addEventListener('popstate',()=>{state.route=location.pathname;state.menu=false;render();});
let modalSubmit=null;
function showDialog(title,body,onSubmit){modalSubmit=onSubmit;const ic=title===t('changePhoto')?'users':title===t('newPost')?'news':title===t('recordPayment')?'wallet':title===t('addVenue')||title===t('editVenue')?'pin':title===t('newMatch')?'calendar':'ball';modal.innerHTML=`<div class="dialog-head"><div class="dialog-heading"><span class="dialog-mark">${icon(ic)}</span><div><span class="dialog-club">BREJA FC</span><h2 id="dialog-title">${esc(title)}</h2></div></div><button type="button" class="icon-button" data-action="dismiss" aria-label="${t('close')}">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!modal.open)modal.showModal();}
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
modal.addEventListener('close',()=>{modalSubmit=null;});
modal.addEventListener('submit',async e=>{e.preventDefault();if(!modalSubmit)return;const submit=e.submitter;submit.disabled=true;modal.querySelector('.dialog-error')?.remove();try{await modalSubmit(new FormData(e.target),e.submitter);modal.close();await refresh();notify(t('saved'));}catch(error){const div=document.createElement('div');div.className='dialog-error';div.setAttribute('role','alert');div.textContent=t(error.message);modal.querySelector('.dialog-body').prepend(div);submit.disabled=false;}});

function shell(content){
 const route=state.route,me=state.data.me;
 const primary=[['/','home','home'],['/matches','matches','calendar'],['/account','account','wallet'],['/news','news','news']].filter(([path])=>!developer()||path!=='/account');
 const management=[['/health','health','shield'],['/members','members','users'],['/payments','payments','wallet'],['/statements','statements','mail'],['/venues','venues','pin'],['/settings','settings','settings']].filter(([path])=>path==='/health'?developer():admin()||['/venues','/settings'].includes(path));
 const current=[...primary,...management,['/profile','profile','users']].find(([path])=>path==='/'?route==='/':route.startsWith(path));
 const nav=items=>items.map(([path,key,ic])=>navLink(path,t(key),ic,`nav-link ${path==='/'?route==='/'?'active':'':route.startsWith(path)?'active':''}`)).join('');
 return `<div class="app-shell"><aside class="sidebar ${state.menu?'is-open':''}" id="side-nav">${brand()}<nav class="nav-group" aria-label="${t('home')}">${nav(primary)}</nav>${manager()?`<div class="nav-label">${t(developer()?'dev':'admin')}</div><nav class="nav-group" aria-label="${t('manage')}">${nav(management)}</nav>`:''}</aside><div class="workspace"><header class="topbar"><button class="icon-button menu-button" data-action="menu" aria-label="${t('menu')}" aria-controls="side-nav" aria-expanded="${state.menu}">${icon('menu')}</button><div class="breadcrumb"><span class="crumb-parent">Breja FC</span><span class="crumb-parent">/</span><strong>${t(current?.[1]||'matches')}</strong></div><div class="top-actions">${languageSelect()}<button class="profile-button" data-action="profile" aria-label="${t('profile')}">${avatar(me.display_name,true,photoFor(me.id))}<span><strong>${esc(me.display_name)}</strong><small>${t(me.role)}</small></span></button></div></header><main id="main" class="page">${content}${state.data.config.development?`<div class="development-note">${icon('shield')}${t('sampleNotice')}</div>`:''}</main></div><nav class="mobile-nav" aria-label="${t('home')}">${primary.map(([path,key,ic])=>navLink(path,t(key),ic,(path==='/'?route==='/':route.startsWith(path))?'active':'')).join('')}</nav></div>`;
}
function hero(m,primary=false){
 const r=mine(m),future=m.status==='open'&&new Date(m.starts_at)>new Date();
 return `<section class="hero"><div class="pitch-art" aria-hidden="true"><span class="pitch-box"></span></div><div class="eyebrow">${esc(localeDate(m.starts_at,{weekday:'long',day:'numeric',month:'long'},m.timezone))}</div><${primary?'h1':'h2'}>${esc(m.title)}</${primary?'h1':'h2'}><div class="hero-meta"><span>${icon('clock')}${time(m.starts_at,m.timezone)}–${time(m.ends_at,m.timezone)}</span><span>${icon('pin')}${esc(m.venue)}</span><span>${icon('users')}${m.occupied}/${m.capacity} ${t('registeredSpots')}</span></div><div class="hero-bottom"><div class="hero-price">${money(m.price_cents)}<small>/ ${t('pricePer')}</small></div><div class="hero-actions">${primary?'':developer()?navLink('/matches/'+m.id,t('viewMatch'),'arrow','btn btn-primary'):future?btn(r?t(r.status==='confirmed'?'joined':r.status):m.occupied>=m.capacity?t('joinWaitlist'):t('join'),r?'view-match':'join',{id:m.id,class:r?'btn-ghost':'btn-primary',icon:r?'check':'plus'}):badge(m.status)}</div></div></section>`;
}
function technicalCard(){return `<section class="card stack"><div class="section-head"><h2>${t('manage')}</h2>${icon('settings')}</div>${navLink('/venues',t('venues'),'pin','btn')}${navLink('/settings',t('settings'),'settings','btn')}</section>`;}
function balanceCard(){const b=state.data.account.balance;return `<section class="card balance-card"><div class="balance-top"><span>${t('yourBalance')}</span>${icon('wallet')}</div><div class="balance-amount">${money(Math.abs(b))}</div><div class="balance-caption"><span class="dot"></span>${t(b>0?'outstanding':b<0?'credit':'settled')}</div>${navLink('/account',t('viewAccount'),'arrow','text-link')}</section>`;}
function personRow(r,actions=false,m=null){return `<div class="list-row"><div class="person">${avatar(r.name,r.mine,photoFor(r.user_id))}<div><strong>${esc(r.name)}${r.mine&&!r.guest?' · '+t('you'):''}</strong>${r.guest?`<small>${esc(t('guestOf',{name:r.sponsor}))}</small>`:''}</div></div><div class="row-actions">${badge(r.attendance||r.status)}${!developer()&&actions&&r.mine&&m?.status==='open'&&new Date(m.starts_at)>new Date()?r.status==='offered'?btn(t('acceptSpot'),'accept',{id:r.id,class:'btn-small btn-primary'}):['confirmed','waitlist'].includes(r.status)?`<button class="icon-button" data-action="cancel-registration" data-id="${r.id}" aria-label="${esc(t(r.guest?'cancelGuest':'cancelSpot'))}">${icon('close')}</button>`:'':''}</div></div>`;}
function leaderboardCard(){const rows=state.data.leaderboard||[];return `<section class="card leaderboard-card"><div class="section-head"><div><div class="eyebrow">${t('clubRanking')}</div><h2>${t('topAppearances')}</h2></div><span class="ranking-symbol">${icon('ball')}</span></div><p class="hint">${t('rankingHint')}</p>${rows.length?rows.map(u=>`<div class="ranking-row ${u.rank===1?'ranking-leader':''}"><span class="ranking-number">${String(u.rank).padStart(2,'0')}</span><div class="person">${avatar(u.display_name,u.id===state.data.me.id,photoFor(u.id))}<strong>${esc(u.display_name)}${u.id===state.data.me.id?' · '+t('you'):''}</strong></div><div class="ranking-count"><strong>${u.appearances}</strong><small>${t('playedMatches')}</small></div></div>`).join(''):empty(t('rankingEmpty'),'','ball')}</section>`;}
function homePage(){const next=currentMatches()[0],news=state.data.news[0];return heading(t('hello',{name:state.data.me.display_name}),t('intro'),manager()?btn(t('createMatch'),'create-match',{class:'btn-primary',icon:'plus'}):'')+
 `<div class="dashboard-top">${next?hero(next):`<section class="card">${empty(t('emptyMatches'),t('emptyMatchesHint'))}</section>`}${developer()?technicalCard():balanceCard()}</div><div class="dashboard-bottom">${leaderboardCard()}<section class="card news-card"><div class="news-symbol">${icon('news')}</div><div class="eyebrow">${t('news')}</div>${news?`${news.image_url?`<img class="news-cover" src="${esc(news.image_url)}" alt="" loading="lazy">`:''}<h3>${esc(newsText(news,'title',lang))}</h3><p>${esc(newsText(news,'body',lang)).slice(0,350)}</p><time>${localeDate(news.created_at)}</time>`:`<h3>${t('noNews')}</h3>`}<div class="section-space">${navLink('/news',t('news'),'arrow','text-link')}</div></section></div><section class="section-space"><div class="section-head"><h2>${t('nextGames')}</h2>${navLink('/matches',t('allMatches'),'arrow','text-link')}</div><div class="match-grid">${currentMatches().slice(1,3).map(matchCard).join('')||`<p class="hint">${t('emptyMatchesHint')}</p>`}</div></section>`;}
function matchCard(m){return `<article class="card match-card"><div class="match-card-header"><div class="person"><div class="date-square"><small>${localeDate(m.starts_at,{day:undefined,month:'short'},m.timezone)}</small><strong>${localeDate(m.starts_at,{month:undefined,day:'numeric'},m.timezone)}</strong></div><div><h3>${esc(m.title)}</h3><div class="metadata">${esc(m.venue)} · ${time(m.starts_at,m.timezone)}<br>${esc(localeDate(m.starts_at,{weekday:'long',day:undefined,month:undefined},m.timezone))}</div></div></div>${badge(m.status)}</div><div class="match-card-footer"><span class="text-small muted">${m.occupied}/${m.capacity} · ${money(m.price_cents)}</span>${navLink('/matches/'+m.id,t('viewMatch'),'arrow','text-link')}</div></article>`;}
function matchesPage(){
 const head=heading(t('matches'),'',manager()?btn(t('createMatch'),'create-match',{class:'btn-primary',icon:'plus'}):'');
 const tabs=`<div class="tabs">${['upcoming','past','calendar'].map(v=>`<button class="tab ${state.matchTab===v?'active':''}" data-action="match-tab" data-id="${v}" aria-pressed="${state.matchTab===v}">${t(v==='upcoming'?'upcomingTab':v)}</button>`).join('')}</div>`;
 if(state.matchTab==='calendar')return head+tabs+calendarPage();
 const list=state.data.matches.filter(m=>state.matchTab==='past'?m.status==='closed'||m.status==='cancelled'||new Date(m.starts_at)<=new Date():m.status!=='closed'&&m.status!=='cancelled'&&new Date(m.starts_at)>new Date()).sort((a,b)=>state.matchTab==='past'?b.starts_at.localeCompare(a.starts_at):a.starts_at.localeCompare(b.starts_at));
 return head+tabs+`<div class="match-grid">${list.map(matchCard).join('')}</div>${!list.length?empty(t('emptyMatches'),t('emptyMatchesHint')):''}`;
}
function calendarPage(){
 const zone=state.data.settings.timezone,today=dayKey(new Date(),zone);state.calendarMonth??=today.slice(0,7);state.calendarDay??=today;
 const month=state.calendarMonth,days=calendarDays(month),grouped=groupMatches(state.data.matches,zone),chosen=grouped[state.calendarDay]||[];
 const dateLabel=key=>localeDate(key+'T12:00:00Z',{weekday:'long',day:'numeric',month:'long',year:'numeric'},'UTC');
 const weekdays=Array.from({length:7},(_,i)=>localeDate(`2026-11-${String(i+2).padStart(2,'0')}T12:00:00Z`,{weekday:'short',day:undefined,month:undefined},'UTC'));
 return `<section class="card calendar-card"><div class="calendar-toolbar"><h2 aria-live="polite">${esc(localeDate(month+'-01T12:00:00Z',{day:undefined,month:'long',year:'numeric'},'UTC'))}</h2><div class="row-actions">${btn(t('today'),'calendar-today',{class:'btn-small'})}<button type="button" class="icon-button" data-action="calendar-month" data-id="-1" aria-label="${t('previousMonth')}">${icon('left')}</button><button type="button" class="icon-button" data-action="calendar-month" data-id="1" aria-label="${t('nextMonth')}">${icon('arrow')}</button></div></div>
 <table class="calendar-grid" aria-label="${t('calendar')}"><thead><tr>${weekdays.map(day=>`<th scope="col">${esc(day)}</th>`).join('')}</tr></thead><tbody>${Array.from({length:6},(_,row)=>`<tr>${days.slice(row*7,row*7+7).map(key=>{const games=grouped[key]||[];return `<td class="${key.startsWith(month)?'':'outside-month'} ${key===state.calendarDay?'selected-day':''} ${key===today?'is-today':''}"><button type="button" class="calendar-day" data-action="calendar-day" data-id="${key}" aria-pressed="${key===state.calendarDay}" ${key===today?'aria-current="date"':''} aria-label="${esc(dateLabel(key)+' · '+t('matchCount',{count:games.length}))}"><span>${Number(key.slice(-2))}</span>${games.length?`<span class="calendar-count">${games.length}</span>`:''}</button><div class="calendar-events">${games.slice(0,2).map(m=>`<a href="/matches/${esc(m.id)}" data-nav="/matches/${esc(m.id)}" class="calendar-event ${m.status==='cancelled'?'is-cancelled':''}" title="${esc(m.title+' · '+m.venue)}"><b>${time(m.starts_at,zone)}</b> ${esc(m.title)}</a>`).join('')}${games.length>2?`<small>+${games.length-2}</small>`:''}</div></td>`;}).join('')}</tr>`).join('')}</tbody></table></section>
 <section class="section-space" aria-live="polite"><div class="section-head"><h2>${esc(dateLabel(state.calendarDay))}</h2><span class="text-small muted">${t('matchCount',{count:chosen.length})}</span></div><div class="match-grid">${chosen.map(matchCard).join('')}</div>${chosen.length?'':empty(t('noMatchesOnDay'),'','calendar')}</section>`;
}

function detailPage(mid){const m=getMatch(mid);if(!m)return empty(t('not_found'));const future=m.status==='open'&&new Date(m.starts_at)>new Date(),regs=m.registrations.filter(r=>!['cancelled','expired'].includes(r.status)),r=mine(m);const deadline=new Date(new Date(m.starts_at)-m.cancel_hours*3600000).toISOString();return `<div class="toolbar">${navLink('/matches',t('backMatches'),'left','text-link')}${btn(t('share'),'share',{id:m.id,icon:'share'})}</div><div class="match-detail-grid"><div class="stack">${hero(m,true)}<section class="card"><div class="section-head"><h2>${t('lineup')}</h2><span class="text-small muted">${m.occupied}/${m.capacity}</span></div>${regs.map(r=>personRow(r,true,m)).join('')||empty(t('noPlayers'))}</section></div><div class="stack">${developer()?'':`<section class="card spot-panel"><div class="section-head"><h2>${t('spot')}</h2>${r?badge(r.status):badge(m.status)}</div><div class="progress"><span style="width:${Math.min(100,m.occupied/m.capacity*100)}%"></span></div>${future?`${r?r.status==='offered'?`<p class="notice">${esc(t('offerUntil',{date:longDate(r.offer_until,m.timezone)}))}</p>${btn(t('acceptSpot'),'accept',{id:r.id,class:'btn-primary btn-full'})}`:r.status==='confirmed'?`${btn(t('joined'),'view-match',{id:m.id,class:'btn-full',icon:'check'})}${btn(t('cancelSpot'),'cancel-registration',{id:r.id,class:'btn-ghost btn-small'})}`:`<p class="notice">${t(r.status)}</p>`:btn(m.occupied>=m.capacity?t('joinWaitlist'):t('join'),'join',{id:m.id,class:'btn-primary btn-full',icon:'plus'})}<p class="hint">${esc(t('freeCancellation',{date:longDate(deadline,m.timezone)}))}</p><hr class="divider">${m.allow_guests?btn(t('bringGuest'),'guest',{id:m.id,class:'btn-full',icon:'plus'}):`<p class="notice">${t('guests_disabled')}</p>`}<p class="hint">${t('guestResponsibility')}</p>`:`<p class="hint">${t(m.status)}</p>`}</section>`}${locationCard(m)}${manager()?`<section class="card"><div class="section-head"><h2>${t('manage')}</h2>${icon('settings')}</div><div class="form-stack">${m.status==='draft'?btn(t('publish'),'publish',{id:m.id,class:'btn-primary'}):''}${admin()&&m.status==='open'&&new Date(m.ends_at)<=new Date()?btn(t('closeMatch'),'close-match',{id:m.id,class:'btn-primary',icon:'check'}):''}${admin()?`<form id="guest-permission-form" data-mid="${esc(m.id)}">${check(t('allowGuests'),'allow_guests',false,!!m.allow_guests)}<p class="hint">${t('guestPermissionHint')}</p><button class="btn" type="submit">${t('save')}</button></form>`:''}${btn(t('duplicate'),'duplicate',{id:m.id,icon:'copy'})}${admin()?btn(t('recordPayment'),'record-payment',{id:m.id,icon:'wallet'}):''}${admin()&&m.status!=='cancelled'?btn(t('cancelMatch'),'cancel-match',{id:m.id,class:'btn-danger'}):''}</div></section>`:''}</div></div>`;}
function entryLabel(e){if(e.kind==='charge'){try{const d=JSON.parse(e.description);return `${t(d.reason)}${d.guest?' · '+d.guest:''}`;}catch{return e.description;}}return t(e.kind);}
function entryDetail(e){if(e.kind==='charge'){try{return JSON.parse(e.description).title;}catch{return '';}}return e.kind==='payment'?`${t(e.method||'other')}${e.payer_name?' · '+e.payer_name:''}`:e.description;}
function linkedMatch(e){const m=e.match_id&&getMatch(e.match_id);return m?`<div class="ledger-match">${navLink('/matches/'+m.id,m.title,'calendar','text-link')}<small>${esc(localeDate(m.starts_at,{year:'numeric'},m.timezone))} · ${esc(m.venue)}</small></div>`:'';}
function ledgerRows(entries,adminView=false){return entries.map(e=>`<tr><td><div class="person">${adminView?avatar(e.display_name):icon(e.kind==='payment'?'wallet':e.kind==='reversal'?'refresh':'ball')}<div>${esc(adminView?e.display_name:entryLabel(e))}<small>${esc(adminView?entryLabel(e):e.match_id&&getMatch(e.match_id)?'':entryDetail(e))}</small>${!adminView?linkedMatch(e):''}</div></div></td><td>${localeDate(e.occurred_at,{year:'numeric'})}${adminView?`<small>${esc(entryDetail(e))}</small>`:''}</td><td class="amount ${e.amount_cents<0?'positive':''}">${e.amount_cents<0?'−':''}${money(Math.abs(e.amount_cents))}</td>${adminView?`<td>${e.kind!=='reversal'&&!state.admin.ledger.some(l=>l.reverses_id===e.id)?`<button class="icon-button" data-action="reverse" data-id="${e.id}" aria-label="${t('reverse')}">${icon('refresh')}</button>`:''}</td>`:''}</tr>`).join('');}
function accountPage(){const {account,settings,statements}=state.data;return heading(t('account'),t('accountIntro'),btn(t('reportPayment'),'report-payment',{class:'btn-primary',icon:'wallet'}))+`<div class="account-grid"><div class="stack">${balanceCard()}<section class="card"><div class="section-head"><h2>${t('paymentInstructions')}</h2></div><p class="hint prewrap">${esc(settings['payment_instructions_'+lang])}</p></section>${account.reports.filter(r=>r.status==='pending').map(r=>`<section class="notice">${t('pendingReport')} · ${money(r.amount_cents)}</section>`).join('')}</div><div class="stack"><section class="card"><div class="section-head"><h2>${t('transactions')}</h2></div>${account.ledger.length?`<div class="table-wrap"><table><thead><tr><th>${t('details')}</th><th>${t('date')}</th><th>${t('amount')}</th></tr></thead><tbody>${ledgerRows(account.ledger)}</tbody></table></div>`:empty(t('noActivity'),'','wallet')}</section><section class="card"><div class="section-head"><h2>${t('statements')}</h2></div>${statements.length?statements.map(s=>`<div class="list-row"><span>${esc(s.month)}</span><div class="row-actions"><span class="amount">${money(s.snapshot.closing)}</span>${btn(t('details'),'own-statement',{id:s.id,class:'btn-small'})}</div></div>`).join(''):`<p class="hint">${t('noStatements')}</p>`}</section></div></div>`;}
function positionOptions(value='',required=false){
 const known=state.data.config.positions||[];
 return [{value:'',label:t(required?'choosePosition':'noPreference')},...known.map(value=>({value,label:t('position_'+value)})),...(value&&!known.includes(value)?[{value,label:value}]:[])];
}
function positionFields(user={},required=false){return field(t('firstPosition'),'position',user.position||'',{required,options:positionOptions(user.position,required)})+field(t('secondPosition'),'position_secondary',user.position_secondary||'',{options:positionOptions(user.position_secondary)});}
function applicationList(){
 const requests=state.admin.applications||[],pending=requests.filter(u=>u.membership_status==='pending'),rejected=requests.filter(u=>u.membership_status==='rejected');
 const card=u=>`<article class="application-card" data-application-id="${esc(u.id)}"><div class="application-person">${avatar(u.display_name)}<div><h3>${esc(u.name)}</h3><p class="hint">${esc(u.email)}</p></div>${badge(u.membership_status,t('membership_'+u.membership_status))}</div><dl class="application-details"><div><dt>${t('dateOfBirth')}</dt><dd>${esc(localeDate(u.birthday+'T12:00:00Z',{year:'numeric'},'UTC'))}</dd></div><div><dt>${t('preferredPositions')}</dt><dd>${[u.position,u.position_secondary].filter(Boolean).map(p=>esc(t('position_'+p))).join(' · ')}</dd></div><div><dt>${t('requestedOn')}</dt><dd>${esc(localeDate(u.application_submitted_at,{year:'numeric'}))}</dd></div></dl>${u.membership_status==='pending'?`<div class="row-actions">${btn(t('acceptApplication'),'approve-application',{id:u.id,class:'btn-primary',icon:'check'})}${btn(t('reject'),'reject-application',{id:u.id,class:'btn-ghost'})}</div>`:''}<div class="row-actions">${btn(t('deleteProfile'),'delete-member',{id:u.id,class:'btn-small btn-ghost'})}</div></article>`;
 return `<section class="card applications-panel"><div class="section-head"><div><h2>${t('joinRequests')} <span class="request-count">${pending.length}</span></h2><p class="hint">${t('joinRequestsHint')}</p></div>${btn(t('checkStatus'),'refresh-membership',{class:'btn-small',icon:'refresh'})}</div>${pending.length?`<div class="application-grid">${pending.map(card).join('')}</div>`:`<p class="hint">${t('noJoinRequests')}</p>`}${rejected.length?`<details class="rejected-applications"><summary>${t('rejectedRequests')} (${rejected.length})</summary><div class="application-grid">${rejected.map(card).join('')}</div></details>`:''}</section>`;
}
function reviewApplicationDialog(uid,decision){
 const user=state.admin.applications.find(u=>u.id===uid);if(!user)return;
 confirmation(t(decision==='approved'?'acceptApplication':'rejectApplication'),t(decision==='approved'?'acceptApplicationHint':'rejectApplicationHint',{name:user.name}),()=>api('/admin/applications/'+uid,'PATCH',{decision}));
}
function membersPage(){return heading(t('members'),'',btn(t('addMember'),'add-member',{icon:'plus',class:'btn-primary'}))+applicationList()+`<div class="toolbar"><label class="search">${icon('search')}<input type="search" id="member-search" value="${esc(state.search)}" placeholder="${t('search')}" aria-label="${t('search')}"></label><span class="muted text-small">${state.admin.members.length} ${t('members')}</span></div><section class="card"><div id="member-list">${memberList()}</div></section>`+archivedMembers();}
function memberList(){const list=state.admin.members.filter(u=>(u.name+' '+u.display_name+' '+u.email).toLowerCase().includes(state.search.toLowerCase()));if(!list.length)return empty(t('noResults'),'','users');return `<div class="table-wrap"><table><thead><tr><th>${t('member')}</th><th>${t('role')}</th><th>${t('balance')}</th><th>${t('action')}</th></tr></thead><tbody>${list.map(u=>`<tr><td><div class="person">${avatar(u.display_name,false,photoFor(u.id))}<div>${esc(u.display_name)}<small>${esc(u.email)}</small></div></div></td><td>${badge('neutral',t(u.role))}</td><td><span class="amount">${money(u.balance)}</span></td><td><div class="row-actions">${btn(t('editRole'),'edit-role',{id:u.id,class:'btn-small'})}${btn(t('recordPayment'),'member-payment',{id:u.id,class:'btn-small'})}${u.id!==state.data.me.id?btn(t('deleteProfile'),'delete-member',{id:u.id,class:'btn-small btn-ghost'}):''}</div></td></tr>`).join('')}</tbody></table></div>`;}
function financialMembers(){return [...state.admin.members,...(state.admin.archivedMembers||[])];}
function archivedMembers(){const list=state.admin.archivedMembers||[];return `<section class="card archived-members"><details><summary>${t('archivedMembers')} (${list.length})</summary><p class="hint">${t('archivedMembersHint')}</p>${list.map(u=>`<div class="list-row"><div><strong>${esc(u.display_name)}</strong><small>${t('deletedOn')} ${esc(localeDate(u.deleted_at,{year:'numeric'}))}</small></div><div class="row-actions"><span class="amount">${money(u.balance)}</span>${btn(t('recordPayment'),'member-payment',{id:u.id,class:'btn-small'})}</div></div>`).join('')||`<p class="hint">${t('noArchivedMembers')}</p>`}</details></section>`;}
function deleteMemberDialog(uid){
 const user=[...state.admin.members,...(state.admin.applications||[])].find(u=>u.id===uid);if(!user||uid===state.data.me.id)return;
 showDialog(t('deleteProfile'),`<form class="form-stack"><div class="person">${avatar(user.display_name)}<div><strong>${esc(user.display_name)}</strong><small>${esc(user.email)}</small></div></div><p class="notice error">${t('deleteProfileWarning')}</p><p class="hint">${t('deleteProfileHistory')}</p><p class="hint">${t('deleteProfileMatches')}</p>${check(t('deleteProfileConfirm'),'confirm')}${formActions('deleteProfile')}</form>`,fd=>api('/admin/members/'+uid,'DELETE',{confirm:fd.has('confirm')}));
}
function roleDialog(uid){const user=state.admin.members.find(u=>u.id===uid);showDialog(t('editRole'),`<form class="form-stack"><div class="person">${avatar(user.display_name,false,photoFor(uid))}<div><strong>${esc(user.display_name)}</strong><small>${esc(user.email)}</small></div></div>${field(t('role'),'role',user.role,{options:['member','admin','dev'].map(value=>({value,label:t(value)}))})}<div class="role-descriptions">${['member','admin','dev'].map(role=>`<div><strong>${t(role)}</strong><p class="hint">${t(role+'Permissions')}</p></div>`).join('')}</div>${formActions()}</form>`,async fd=>{await api('/admin/members/'+uid+'/role','PATCH',{role:fd.get('role')});if(uid===state.data.me.id){state.route='/';history.replaceState({},'','/');}});}
function paymentsPage(){const due=financialMembers().reduce((n,u)=>n+Math.max(0,u.balance),0),received=state.admin.stats.received;return heading(t('payments'),t('accountIntro'),`<a class="btn" href="/api/admin/export" download>${icon('download')}${t('export')}</a>${btn(t('recordPayment'),'record-payment',{class:'btn-primary',icon:'plus'})}`)+`<div class="summary-strip"><div class="stat"><small>${t('totalDue')}</small><strong>${money(due)}</strong></div><div class="stat"><small>${t('received')}</small><strong>${money(received)}</strong></div><div class="stat"><small>${t('needsReview')}</small><strong>${state.admin.reports.length}</strong></div></div><div class="stack"><section class="card"><div class="section-head"><h2>${t('needsReview')}</h2></div>${state.admin.reports.map(r=>`<div class="list-row"><div class="person">${avatar(r.display_name)}<div><strong>${esc(r.display_name)} · ${money(r.amount_cents)}</strong><small>${t(r.method)}${r.note?' · '+esc(r.note):''}</small></div></div><div class="row-actions">${btn(t('confirmReceived'),'confirm-report',{id:r.id,class:'btn-small btn-primary'})}${btn(t('reject'),'reject-report',{id:r.id,class:'btn-small btn-ghost'})}</div></div>`).join('')||`<p class="hint">${t('noReports')}</p>`}</section><section class="card"><div class="section-head"><h2>${t('transactions')}</h2></div><div class="table-wrap"><table><thead><tr><th>${t('member')}</th><th>${t('date')}</th><th>${t('amount')}</th><th>${t('action')}</th></tr></thead><tbody>${ledgerRows(state.admin.ledger,true)}</tbody></table></div></section></div>`;}
function previousMonth(){const p=new Date();p.setUTCDate(1);p.setUTCMonth(p.getUTCMonth()-1);return p.toISOString().slice(0,7);}
function statementsPage(){return heading(t('statements'),t('statementIntro'))+`<div class="stack"><section class="card"><form id="statement-preview" class="form-stack"><div class="form-grid">${field(t('month'),'month',state.statementPreview?.month||previousMonth(),{type:'month',required:true,max:previousMonth()})}<div class="field"><span>&nbsp;</span><button class="btn btn-dark" type="submit">${icon('search')}${t('preview')}</button></div></div><p class="hint">${t('statementHint')}</p></form><div id="statement-results">${statementResults()}</div></section><section class="card"><div class="section-head"><h2>${t('outbox')}</h2>${icon('mail')}</div>${state.data.config.development?`<p class="notice">${t('localMail')}</p>`:''}${state.admin.outbox.map(m=>`<div class="list-row"><div><strong class="text-small">${esc(m.subject)}</strong><p class="hint">${esc(m.recipient)}</p></div><div class="row-actions">${badge(m.status)}${btn(t('viewMessage'),'view-message',{id:m.id,class:'btn-small'})}</div></div>`).join('')||`<p class="hint">${t('noStatements')}</p>`}</section></div>`;}
function statementResults(){const p=state.statementPreview;if(!p)return '';if(!p.statements.length)return `<p class="notice">${t('noStatementActivity')}</p>`;return `<hr class="divider"><div class="section-head"><h2>${esc(t('statementsReady',{count:p.statements.length}))}</h2>${btn(t('generate'),'generate-statements',{class:'btn-primary',icon:'mail'})}</div><div class="table-wrap"><table><thead><tr><th>${t('member')}</th><th>${t('previousBalance')}</th><th>${t('monthEnd')}</th><th>${t('currentBalance')}</th></tr></thead><tbody>${p.statements.map(s=>`<tr><td>${esc(s.user.display_name)}</td><td class="amount">${money(s.opening)}</td><td class="amount">${money(s.closing)}</td><td class="amount">${money(s.current)}</td></tr>`).join('')}</tbody></table></div>`;}
function newsCard(n,language=lang){return `<article class="card news-post ${n.pinned?'news-card':''}">${n.image_url?`<img class="news-cover" src="${esc(n.image_url)}" alt="" loading="lazy">`:''}${n.pinned?badge('confirmed',t('pinned')):''}<h2>${esc(newsText(n,'title',language))}</h2><p>${esc(newsText(n,'body',language))}</p>${n.created_at?`<time>${localeDate(n.created_at,{year:'numeric'})}</time>`:''}</article>`;}
function newsPage(){return heading(t('news'),t('newsIntro'),admin()?btn(t('newPost'),'new-post',{class:'btn-primary',icon:'plus'}):'')+`<div class="news-grid">${state.data.news.map(n=>newsCard(n)).join('')}</div>${!state.data.news.length?empty(t('noNews'),'','news'):''}`;}
function profilePage(){const u=state.data.me;return heading(t('profile'),'',btn(t('logout'),'logout',{icon:'logout'}))+`<div class="profile-layout"><section class="card profile-summary"><div class="profile-portrait">${avatar(u.display_name,false,photoFor(u.id))}</div><h2>${esc(u.display_name)}</h2><p class="hint">${esc(u.email)}</p>${badge('confirmed',t(u.role))}<div class="profile-photo-actions">${btn(t('changePhoto'),'profile-photo',{icon:'plus',class:'btn-primary'})}${photoFor(u.id)?btn(t('removeImage'),'remove-profile-photo',{class:'btn-ghost btn-small'}):''}</div><p class="hint">${t('photoVisibility')}</p></section><form id="profile-form" class="card form-stack"><div class="form-section-title">${icon('users')}<h2>${t('personalDetails')}</h2></div><div class="form-grid">${field(t('name'),'name',u.name,{required:true,autocomplete:'name'})}${field(t('displayName'),'display_name',u.display_name,{required:true})}${field(t('email'),'email',u.email,{readonly:true,type:'email'})}${field(t('phone'),'phone',u.phone,{type:'tel',autocomplete:'tel'})}${field(t(u.application_submitted_at?'dateOfBirth':'birthday'),'birthday',u.birthday,{type:'date',required:!!u.application_submitted_at,min:'1900-01-01',max:new Date().toISOString().slice(0,10)})}${positionFields(u,!!u.application_submitted_at)}${field(t('language'),'language',u.language,{options:[{value:'en',label:'English'},{value:'de',label:'Deutsch'},{value:'es',label:'Español'}]})}</div><p class="notice">${icon('shield')}${t('profilePrivacy')}</p><div class="form-actions"><button type="submit" class="btn btn-primary">${icon('check')}${t('save')}</button></div></form></div>`;}
function profilePhotoDialog(){let data='';const user=state.data.me;
 showDialog(t('changePhoto'),`<form class="form-stack"><div class="photo-preview profile-portrait" id="profile-photo-preview">${avatar(user.display_name,false,photoFor(user.id))}</div><label class="field image-picker"><span>${t('choosePhoto')}</span><input type="file" id="profile-photo-file" accept="image/jpeg,image/png,image/webp"><small>${t('imageHint')}</small></label><p class="hint" role="status" id="profile-photo-status">${t('photoCropHint')}</p>${formActions()}</form>`,()=>api('/profile/photo','POST',{image_data:data}));
 const form=modal.querySelector('form'),save=form.querySelector('[type="submit"]'),input=form.querySelector('#profile-photo-file');save.disabled=true;
 input.onchange=async()=>{const file=input.files[0];if(!file)return;save.disabled=true;input.disabled=true;const status=form.querySelector('#profile-photo-status');status.textContent=t('imageLoading');
  try{const result=await prepareNewsImage(file,true);if(!form.isConnected)return;data=result;form.querySelector('#profile-photo-preview').innerHTML=avatar(user.display_name,false,data);save.disabled=false;status.textContent=t('photoCropHint');}
  catch(error){status.textContent=t(error.message);input.value='';}
  finally{input.disabled=false;}
 };
}
function createMemberDialog(){showDialog(t('addMember'),`<form class="form-stack"><div class="form-grid">${field(t('name'),'name','',{required:true,wide:true,autocomplete:'name',maxLength:100})}${field(t('displayName'),'display_name','',{maxLength:60})}${field(t('language'),'language',lang,{options:[{value:'en',label:'English'},{value:'de',label:'Deutsch'},{value:'es',label:'Español'}]})}${field(t('email'),'email','',{type:'email',required:true,wide:true,autocomplete:'email',maxLength:254})}</div><p class="notice">${t('manualMemberHint')}</p>${formActions('addMember')}</form>`,fd=>api('/admin/members','POST',Object.fromEntries(fd)));}

function venueOptions(){return [{value:'',label:t('chooseVenue')},{value:'custom',label:t('customVenue')},...state.data.venues.filter(v=>!v.archived).map(v=>({value:v.id,label:v.name+(v.address?' · '+v.address:'')}))];}
function directions(v){const url=mapLink(v);return url?`<a class="text-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${t('directions')}${icon('arrow')}</a>`:'';}
function venueMap(v){const src=mapEmbed(v);return src?`<iframe class="venue-map" src="${esc(src)}" title="${esc(t('mapOf',{name:v.name||v.venue}))}" loading="lazy" referrerpolicy="no-referrer" allowfullscreen></iframe>`:'';}
function locationCard(m){return `<section class="card"><div class="section-head"><h2>${t('location')}</h2>${icon('pin')}</div><strong>${esc(m.venue)}</strong>${m.address?`<p class="hint">${esc(m.address)}</p>`:''}${venueMap(m)}${directions(m)||`<p class="hint">${t('locationPending')}</p>`}</section>`;}
function venuesPage(){return heading(t('venues'),'',btn(t('addVenue'),'create-venue',{class:'btn-primary',icon:'plus'}))+`<div class="match-grid">${state.data.venues.map(v=>`<article class="card venue-card ${v.archived?'venue-archived':''}"><div class="section-head"><h2>${esc(v.name)}</h2>${badge(v.archived?'expired':'confirmed',t(v.archived?'archived':'season_'+v.season))}</div><p class="hint">${esc(v.address||(!v.map_url?t('locationPending'):''))}</p>${venueMap(v)}${directions(v)}<div class="venue-actions">${btn(t('editVenue'),'edit-venue',{id:v.id,class:'btn-small'})}${btn(t(v.archived?'restore':'archive'),v.archived?'restore-venue':'archive-venue',{id:v.id,class:'btn-small btn-ghost'})}</div></article>`).join('')}</div>${!state.data.venues.length?empty(t('noVenues'),'','pin'):''}`;}
function venueDialog(venue){showDialog(t(venue?'editVenue':'addVenue'),`<form><div class="form-grid">${field(t('venueName'),'name',venue?.name||'',{required:true,wide:true,maxLength:120})}${field(t('season'),'season',venue?.season||'all',{wide:true,options:['all','summer','winter'].map(value=>({value,label:t('season_'+value)}))})}${field(t('address'),'address',venue?.address||'',{wide:true})}${field(t('mapUrl'),'map_url',venue?.map_url||'',{wide:true,type:'url',maxLength:2000,placeholder:'https://…'})}</div><p class="hint">${t('locationRequired')}</p><div id="venue-form-map" class="venue-form-map"></div>${formActions()}</form>`,fd=>api('/admin/venues'+(venue?'/'+venue.id:''),venue?'PATCH':'POST',Object.fromEntries(fd)));
 const form=modal.querySelector('form'),preview=form.querySelector('#venue-form-map');let pending;
 const update=()=>{if(!form.isConnected)return;const v=Object.fromEntries(new FormData(form));preview.innerHTML=venueMap(v)||`<div class="map-placeholder">${icon('pin')}<p>${t('mapAddressHint')}</p></div>`;};
 form.addEventListener('input',e=>{if(['name','address'].includes(e.target.name)){clearTimeout(pending);pending=setTimeout(update,650);}});update();
}
function settingsPage(){const s=state.data.settings;return heading(t('settings'),'')+`<form id="settings-form" class="stack"><section class="card form-section"><h2>${t('defaults')}</h2><p class="hint">${t('settingsHint')}</p><div class="form-grid">${field(t('price'),'price',s.price_cents/100,{type:'number',required:true,min:0,max:10000,step:'.01'})}${field(t('capacity'),'capacity',s.capacity,{type:'number',min:2,max:100,required:true})}${field(t('cancelHours'),'cancel_hours',s.cancel_hours,{type:'number',min:0,max:168,required:true})}${field(t('timezone'),'timezone',s.timezone,{required:true})}</div></section>${admin()?`<section class="card form-section"><h2>${t('paymentInstructions')}</h2><div class="form-grid">${field(t('english'),'payment_instructions_en',s.payment_instructions_en,{area:true,required:true,max:1000})}${field(t('german'),'payment_instructions_de',s.payment_instructions_de,{area:true,required:true,max:1000})}${field(t('spanish'),'payment_instructions_es',s.payment_instructions_es,{area:true,required:true,max:1000,wide:true})}</div></section>`:''}<div class="form-actions"><button type="submit" class="btn btn-primary">${icon('check')}${t('save')}</button></div></form>`;}

function humanVerification(action){return state.data.config.turnstileSiteKey?`<div class="human-check" data-human-action="${action}"><div id="human-widget"></div><p class="hint" role="status" id="human-status">${t('human_verification_required')}</p>${btn(t('retryVerification'),'retry-verification',{class:'btn-small btn-ghost'})}</div>`:'';}
function mountHumanVerification(){
 if(!state.data.config.turnstileSiteKey)return;
 const element=document.getElementById('human-widget');if(!element)return;
 const action=element.parentElement.dataset.humanAction,status=document.getElementById('human-status');
 void mountTurnstile(element,state.data.config.turnstileSiteKey,action,lang,key=>{if(status.isConnected)status.textContent=t(key);}).catch(()=>{if(status.isConnected)status.textContent=t('human_verification_unavailable');});
}
function protectedFormData(form,p){return {...p,...(state.data.config.turnstileSiteKey?{turnstile_token:turnstileToken(form)}:{})};}
function securitySummary(){const s=state.health?.security;if(!s)return '';return `<section class="card form-section security-panel"><h2>${t('securityHeading')}</h2><p class="hint">${t('applicationMailNotice')}</p><div class="security-summary"><div><small>${t('botProtection')}</small><strong>${t(s.turnstile?'securityEnabled':'securityPending')}</strong></div><div><small>${t('mailBudgetDay')}</small><strong>${s.emailDailyUsed} / ${s.emailDailyLimit}</strong></div><div><small>${t('mailBudgetMonth')}</small><strong>${s.emailMonthlyUsed} / ${s.emailMonthlyLimit}</strong></div></div><p class="hint">${t('mailBudgetHint')}</p></section>`;}
function healthTime(value){return value?esc(localeDate(value,{year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'})):'—';}
function healthEvents(rows){return `<div class="table-wrap"><table class="health-events"><thead><tr><th>${t('healthChecked')}</th><th>${t('healthEvent')}</th><th>${t('healthArea')}</th><th>${t('healthActor')}</th><th>${t('healthCode')}</th><th>${t('healthCount')}</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${healthTime(e.last_at)}</td><td><strong>${esc(t('event_'+e.event.replaceAll('.','_')))}</strong><small>${esc(t('healthLevel_'+e.level))}</small></td><td>${esc(t('healthScope_'+e.scope))}</td><td>${esc(t(e.role==='system'?'healthSystem':e.role==='anonymous'?'healthAnonymous':e.role))}</td><td><code>${esc(e.code)}</code>${e.status?`<small>HTTP ${e.status}</small>`:''}</td><td>${e.occurrences}</td></tr>`).join('')}</tbody></table></div>`;}
function healthPage(){
 const h=state.health,head=heading(t('health'),t('healthIntro'),btn(t('healthRefresh'),'refresh-health',{icon:'refresh',class:'btn-primary'}));
 if(!h)return head+`<section class="card">${empty(t(state.healthError?'healthUnavailable':'healthLoading'),'','shield')}</section>`;
 const r=h.runtime,uptime=`${Math.floor(r.uptimeSeconds/86400)}d ${Math.floor(r.uptimeSeconds/3600)%24}h ${Math.floor(r.uptimeSeconds/60)%60}m`;
 return head+`<div class="health-status">${badge(h.status==='operational'?'confirmed':'waitlist',t(h.status==='operational'?'healthOperational':'healthAttention'))}<span class="hint">${t('healthChecked')} · ${healthTime(h.checkedAt)}</span></div><div class="summary-strip health-metrics"><div class="stat"><small>${t('healthUptime')}</small><strong>${uptime}</strong></div><div class="stat"><small>${t('healthMemory')}</small><strong>${r.memoryMB} MB</strong></div><div class="stat"><small>${t('healthDatabase')}</small><strong>${t(r.database?'healthConnected':'healthAttention')}</strong></div><div class="stat"><small>${t('healthErrors24')}</small><strong>${h.errors24h}</strong></div></div>`+securitySummary()+`<div class="stack"><section class="card"><div class="section-head"><h2>${t('healthMail')}</h2>${icon('mail')}</div>${h.mail.budgetBlocked?`<p class="notice">${t('healthBudgetPaused')}</p>`:''}<div class="security-summary"><div><small>${t('healthQueue')}</small><strong>${h.mail.queued}</strong></div><div><small>${t('healthFailed')}</small><strong>${h.mail.failed}</strong></div><div><small>${t('healthSent')}</small><strong>${h.mail.sent}</strong></div><div><small>${t('healthLastMail')}</small><strong class="health-date">${healthTime(h.mail.lastSentAt)}</strong></div></div>${h.mail.oldestQueuedAt?`<p class="hint">${t('healthOldestMail')} · ${healthTime(h.mail.oldestQueuedAt)}</p>`:''}</section><section class="card"><div class="section-head"><h2>${t('healthActivity')}</h2>${icon('shield')}</div><p class="hint">${t('healthRetention')}</p>${h.activity.length?healthEvents(h.activity):empty(t('healthEmpty'),'','shield')}</section><section class="card"><div class="section-head"><h2>${t('healthErrors')}</h2>${icon('settings')}</div>${h.errors.length?healthEvents(h.errors):empty(t('healthNoErrors'),'','check')}</section><p class="hint">${t('healthPrivacy')}</p></div>`;
}
function authPage(){const publicMatch=state.publicMatch;return `<main id="main" class="auth-shell"><section class="auth-brand">${brand()}<div class="pitch-art" aria-hidden="true"></div><h1>${esc(t('hero'))}</h1></section><section class="auth-side"><div class="auth-language">${languageSelect()}</div><div class="auth-box"><h2>${t('signin')}</h2><p>${t('signinIntro')}</p>${publicMatch?`<div class="notice"><strong>${esc(publicMatch.title)}</strong><br>${longDate(publicMatch.starts_at,publicMatch.timezone)}<br>${esc(publicMatch.venue)} · ${money(publicMatch.price_cents)}${publicMatch.address?`<br>${esc(publicMatch.address)}`:''}<div class="section-space">${directions(publicMatch)}</div></div><hr class="divider">`:''}${state.data.config.firebase&&!state.auth?`<button type="button" class="btn google-button" data-action="google-login"><span class="google-g" aria-hidden="true">G</span>${t('googleSignIn')}</button><div class="auth-or">${t('orEmail')}</div>`:''}${state.auth?`<form id="auth-verify" class="form-stack"><p class="hint">${t('codeSent')}</p>${state.auth.developmentCode?`<p class="notice">${esc(t('localCode',{code:state.auth.developmentCode}))}</p>`:''}${field(t('code'),'code','',{required:true,autocomplete:'one-time-code',placeholder:'000000'})}<button type="submit" class="btn btn-primary">${t('verify')}${icon('arrow')}</button>${btn(t('cancel'),'reset-auth',{class:'btn-ghost'})}</form>`:`<form id="auth-request" class="form-stack">${field(t('name'),'name','',{required:true,autocomplete:'name'})}${field(t('email'),'email','',{type:'email',required:true,autocomplete:'email'})}${humanVerification('login_email')}<button type="submit" class="btn btn-primary">${t('sendCode')}${icon('arrow')}</button></form>`}${state.data.config.development?`<div class="auth-divider">${t('development')} · ${t('localMail')}</div><div class="demo-actions">${btn(t('demoAdmin'),'demo-admin',{icon:'shield'})}${btn(t('demoMember'),'demo-member',{icon:'users'})}</div>`:''}</div></section></main>`;}

function render(){if(state.data?.config.turnstileSiteKey)clearTurnstile();document.documentElement.lang=lang;if(!state.data)return;if(!state.data.me){app.innerHTML=authPage();mountHumanVerification();return;}if(state.data.me.membership_status!=='approved'){app.innerHTML=membershipPage();mountHumanVerification();document.title='Breja FC · '+t('joinClub');return;}if(state.route.startsWith('/m/')){const token=state.route.split('/').at(-1),m=state.data.matches.find(m=>m.share_token===token);if(m){state.route='/matches/'+m.id;history.replaceState({},'',state.route);}}
 const route=state.route;let page;
 if(route==='/health'&&developer())page=healthPage();else if(route==='/')page=homePage();else if(route==='/matches')page=matchesPage();else if(route.startsWith('/matches/'))page=detailPage(route.split('/').at(-1));else if(route==='/account'&&!developer())page=accountPage();else if(route==='/news')page=newsPage();else if(route==='/profile')page=profilePage();else if(manager()&&route==='/venues')page=venuesPage();else if(manager()&&route==='/settings')page=settingsPage();else if(admin()&&state.admin){page=({'/members':membersPage,'/payments':paymentsPage,'/statements':statementsPage,'/venues':venuesPage,'/settings':settingsPage}[route]||(()=>empty(t('not_found'))))();}else page=empty(t('not_found'));
 app.innerHTML=shell(page);document.title=`Breja FC · ${t(route==='/health'&&developer()?'health':route==='/account'?'account':route.startsWith('/matches')?'matches':'home')}`;
}

function zonedISO(day,clock,zone){const wall=Date.parse(`${day}T${clock}:00Z`);if(!Number.isFinite(wall))throw new Error('invalid_date');let candidate=wall;for(let i=0;i<3;i++){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(candidate)).map(p=>[p.type,p.value]));const represented=Date.parse(`${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}:${parts.second}Z`);candidate-=represented-wall;}const checkParts=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(candidate)).map(p=>[p.type,p.value]));if(`${checkParts.year}-${checkParts.month}-${checkParts.day}`!==day||`${checkParts.hour}:${checkParts.minute}`!==clock)throw new Error('invalid_date');return new Date(candidate).toISOString();}
function venuePreview(v){return `<strong>${esc(v.name)}</strong><p class="hint">${esc(v.address||(!v.map_url?t('locationPending'):''))}</p>${directions(v)}`;}
function createMatchDialog(source){const s=state.data.settings,selected=null;let day=new Date();day.setDate(day.getDate()+1);const dayString=`${day.getFullYear()}-${String(day.getMonth()+1).padStart(2,'0')}-${String(day.getDate()).padStart(2,'0')}`;
 showDialog(t('newMatch'),`<form><div class="form-grid"><div class="form-step wide"><span>01</span>${t('matchDetails')}</div>${field(t('title'),'title',source?.title||t('hero'),{required:true,wide:true})}${field(t('date'),'date',dayString,{type:'date',required:true,wide:true,min:new Date().toISOString().slice(0,10)})}${field(t('start'),'start','10:00',{type:'time',required:true})}${field(t('end'),'end','11:30',{type:'time',required:true})}<div class="form-step wide"><span>02</span>${t('location')}</div>${field(t('venue'),'venue_id',source?'custom':'',{options:venueOptions(),wide:true,required:true})}<div id="venue-preview" class="venue-preview" ${selected?'':'hidden'}>${selected?venuePreview(selected):''}</div><div id="venue-fields" class="venue-fields" ${source?'':'hidden'}>${field(t('venueName'),'venue',source?.venue||selected?.name||'',{required:true,readonly:!!selected,maxLength:120,wide:true})}${field(t('address'),'address',source?.address||selected?.address||'',{wide:true,readonly:!!selected})}${field(t('mapUrl'),'map_url',source?.map_url||selected?.map_url||'',{wide:true,type:'url',maxLength:2000,readonly:!!selected})}</div><div class="form-step wide"><span>03</span>${t('participation')}</div>${field(t('price'),'price',(source?.price_cents??s.price_cents)/100,{type:'number',required:true,min:0,max:10000,step:'.01'})}${field(t('capacity'),'capacity',source?.capacity||s.capacity,{type:'number',required:true,min:2,max:100})}${field(t('cancelHours'),'cancel_hours',source?.cancel_hours??s.cancel_hours,{type:'number',required:true,min:0,max:168,wide:true})}${admin()?check(t('allowGuests'),'allow_guests',false,!!source?.allow_guests):''}${check(t('saveDraft'),'draft',false)}</div>${formActions('createMatch')}</form>`,async fd=>{const p=Object.fromEntries(fd);const m=await api('/admin/matches','POST',{title:p.title,starts_at:zonedISO(p.date,p.start,s.timezone),ends_at:zonedISO(p.date,p.end,s.timezone),venue_id:p.venue_id==='custom'?null:p.venue_id,venue:p.venue,address:p.address,map_url:p.map_url,capacity:Number(p.capacity),price_cents:Math.round(Number(p.price)*100),cancel_hours:Number(p.cancel_hours),allow_guests:admin()&&fd.has('allow_guests'),status:p.draft?'draft':'open'});state.route='/matches/'+m.id;history.pushState({},'',state.route);});
 const custom={venue:source?.venue||'',address:source?.address||'',map_url:source?.map_url||''};
 let wasCustom=!!source;
 for(const input of modal.querySelectorAll('#venue-fields input'))input.disabled=!source;
 modal.querySelector('[name="venue_id"]').addEventListener('change',e=>{
  if(wasCustom)for(const key of Object.keys(custom))custom[key]=modal.querySelector(`[name="${key}"]`).value;
  const v=state.data.venues.find(v=>v.id===e.target.value);const values=v?{venue:v.name,address:v.address,map_url:v.map_url}:custom;
  for(const [key,value] of Object.entries(values)){const input=modal.querySelector(`[name="${key}"]`);input.value=value;input.readOnly=!!v;input.disabled=e.target.value!=='custom';}
  modal.querySelector('#venue-fields').hidden=e.target.value!=='custom';
  const preview=modal.querySelector('#venue-preview');preview.hidden=!v;preview.innerHTML=v?venuePreview(v):'';
  wasCustom=e.target.value==='custom';
 });
}

