function cancelDialog(rid){const {m,r}=findRegistration(rid),late=r.status==='confirmed'&&new Date(m.starts_at)-Date.now()<m.cancel_hours*3600000;showDialog(t('cancelTitle'),`<form class="form-stack"><p class="${late?'notice error':'hint'}">${esc(late?t('lateWarning',{hours:m.cancel_hours,price:money(m.price_cents)}):t('freeWarning'))}</p>${late?check(t('acceptFee'),'accept_fee'):''}${formActions('confirm')}</form>`,fd=>api(`/registrations/${rid}/cancel`,'POST',{accept_fee:fd.has('accept_fee')}));}
function shareDialog(mid){const m=getMatch(mid),link=location.origin+'/m/'+m.share_token,message=invitation(m,location.origin);showDialog(t('share'),`<p class="hint">${t('shareEnglish')}</p><div class="share-preview prewrap" lang="en">${esc(message)}</div>${field(t('copyLink'),'share-link',link,{readonly:true})}<textarea id="share-message" hidden>${esc(message)}</textarea><div class="form-actions">${btn(t('copyMessage'),'copy-message',{class:'btn-primary',icon:'copy'})}${btn(t('copyLink'),'copy-share',{icon:'copy'})}<a class="btn" href="https://wa.me/?text=${encodeURIComponent(message)}" target="_blank" rel="noopener noreferrer">${icon('share')}${t('whatsapp')}</a></div>`);}
