async function prepareNewsImage(file,square=false){
 if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('invalid_image');
 if(file.size>10*1024*1024)throw new Error('image_too_large');
 const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('invalid_image'));reader.readAsDataURL(file);});
 const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('invalid_image'));img.src=data;});
 const scale=Math.min(1,1600/Math.max(image.width,image.height)),canvas=document.createElement('canvas');
 canvas.width=square?512:Math.max(1,Math.round(image.width*scale));canvas.height=square?512:Math.max(1,Math.round(image.height*scale));
 const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);if(square){const side=Math.min(image.width,image.height);ctx.drawImage(image,(image.width-side)/2,(image.height-side)/2,side,side,0,0,512,512);}else ctx.drawImage(image,0,0,canvas.width,canvas.height);
 const result=canvas.toDataURL('image/jpeg',.85);if(result.length>2800000)throw new Error('image_too_large');return result;
}
function newPostDialog(){
 let editorLanguage=lang,imageData='',imageLoading=false,preview=false;
 const languages=[['en','English'],['de','Deutsch'],['es','Español']];
 showDialog(t('newPost'),`<form id="news-form" class="form-stack" novalidate>
  <div class="tabs news-language-tabs" role="tablist" aria-label="${t('language')}">${languages.map(([code,name])=>`<button type="button" role="tab" id="news-tab-${code}" aria-controls="news-panel-${code}" aria-selected="${code===lang}" tabindex="${code===lang?0:-1}" data-news-language="${code}" class="tab ${code===lang?'active':''}">${name}</button>`).join('')}</div>
  <div id="news-editor">${languages.map(([code])=>`<section class="form-stack" role="tabpanel" id="news-panel-${code}" aria-labelledby="news-tab-${code}" ${code===lang?'':'hidden'}>${field(t('title'),'title_'+code,'',{maxLength:160})}${field(t('body'),'body_'+code,'',{area:true,max:4000})}</section>`).join('')}
   <p class="hint">${t('newsLanguagesHint')}</p>
   <label class="field image-picker"><span>${t('newsImage')}</span><input id="news-image" type="file" accept="image/jpeg,image/png,image/webp"><small>${t('imageHint')}</small></label>
   <div id="news-image-status" class="hint" role="status"></div>
   <div id="news-image-preview" hidden><img class="news-cover" alt=""><button type="button" class="btn btn-small btn-ghost" id="remove-news-image">${t('removeImage')}</button></div>
   <div class="section-space">${check(t('pin'),'pinned',false)}</div>
  </div>
  <div id="news-preview" hidden aria-live="polite"></div>
  <div class="form-actions">${btn(t('cancel'),'dismiss',{class:'btn-ghost'})}<button type="button" class="btn" id="toggle-news-preview">${t('previewPost')}</button><button class="btn btn-primary" type="submit">${t('publishPost')}</button></div>
 </form>`,async fd=>{
  if(imageLoading)throw new Error('imageLoading');
  const input=Object.fromEntries(fd);let count=0;
  for(const [code] of languages){const title=input['title_'+code].trim(),body=input['body_'+code].trim();if(Boolean(title)!==Boolean(body)){preview=false;selectLanguage(code);form.querySelector(`[name="${title?'body':'title'}_${code}"]`).focus();throw new Error('news_translation_incomplete');}if(title)count++;}
  if(!count){preview=false;selectLanguage(editorLanguage);throw new Error('news_content_required');}
  await api('/admin/news','POST',{...input,image_data:imageData,pinned:fd.has('pinned')});
 });
 const form=modal.querySelector('#news-form');
 const draft=()=>({...Object.fromEntries(new FormData(form)),image_url:imageData,pinned:form.querySelector('[name="pinned"]').checked});
 function renderPreview(){const post=draft();form.querySelector('#news-editor').hidden=preview;form.querySelector('#news-preview').hidden=!preview;form.querySelector('#toggle-news-preview').textContent=t(preview?'editPost':'previewPost');form.querySelector('#news-preview').innerHTML=newsText(post,'title',editorLanguage)?newsCard(post,editorLanguage):empty(t('previewEmpty'),'','news');}
 function selectLanguage(code){editorLanguage=code;for(const [id] of languages){const tab=form.querySelector('#news-tab-'+id);tab.classList.toggle('active',id===code);tab.setAttribute('aria-selected',String(id===code));tab.tabIndex=id===code?0:-1;form.querySelector('#news-panel-'+id).hidden=id!==code;}renderPreview();}
 for(const tab of form.querySelectorAll('[data-news-language]')){
  tab.onclick=()=>selectLanguage(tab.dataset.newsLanguage);
  tab.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const current=languages.findIndex(([code])=>code===editorLanguage),index=e.key==='Home'?0:e.key==='End'?2:(current+(e.key==='ArrowRight'?1:2))%3;selectLanguage(languages[index][0]);form.querySelector('#news-tab-'+editorLanguage).focus();};
 }
 form.querySelector('#toggle-news-preview').onclick=()=>{preview=!preview;renderPreview();};
 const upload=form.querySelector('#news-image'),status=form.querySelector('#news-image-status'),imagePreview=form.querySelector('#news-image-preview');
 upload.onchange=async()=>{
  const file=upload.files[0];if(!file)return;imageLoading=true;upload.disabled=true;form.querySelector('[type="submit"]').disabled=true;status.textContent=t('imageLoading');
  try{const result=await prepareNewsImage(file);if(!form.isConnected)return;imageData=result;imagePreview.hidden=false;imagePreview.querySelector('img').src=result;status.textContent='';renderPreview();}
  catch(error){status.textContent=t(error.message);upload.value='';}
  finally{imageLoading=false;upload.disabled=false;form.querySelector('[type="submit"]').disabled=false;}
 };
 form.querySelector('#remove-news-image').onclick=()=>{imageData='';upload.value='';imagePreview.hidden=true;imagePreview.querySelector('img').removeAttribute('src');status.textContent='';renderPreview();};
}


function membershipPage(){
 const u=state.data.me,stage=u.membership_status,onboarding=stage==='onboarding';
 const title=onboarding?'joinClub':stage==='pending'?'applicationPending':'applicationRejected';
 const hint=onboarding?'joinClubIntro':stage==='pending'?'applicationPendingHint':'applicationRejectedHint';
 return `<main id="main" class="auth-shell membership-shell"><section class="auth-brand">${brand()}<div class="pitch-art" aria-hidden="true"></div><h1>${t('joinClubHero')}</h1></section><section class="auth-side"><div class="auth-language">${languageSelect()}</div><div class="auth-box membership-box"><div class="membership-step">${icon(onboarding?'users':stage==='pending'?'clock':'shield')}<span>${t('membership_'+stage)}</span></div><h2>${t(title)}</h2><p>${t(hint)}</p><p class="membership-identity">${esc(u.email)}</p>${onboarding?`<form id="membership-form" class="form-stack"><div class="form-grid">${field(t('name'),'name',u.name,{required:true,wide:true,autocomplete:'name',maxLength:100})}${field(t('displayName'),'display_name',u.display_name,{required:true,wide:true,maxLength:60})}${field(t('dateOfBirth'),'birthday',u.birthday,{type:'date',required:true,wide:true,min:'1900-01-01',max:new Date().toISOString().slice(0,10)})}${positionFields(u,true)}</div><p class="notice">${t('applicationPrivacy')}</p>${humanVerification('membership')}<button type="submit" class="btn btn-primary">${icon('arrow')}${t('submitApplication')}</button></form>`:`<div class="notice ${stage==='rejected'?'error':''}">${t('applicationNoAccess')}</div>${btn(t('checkStatus'),'refresh-membership',{icon:'refresh',class:'btn-primary'})}`}<div class="membership-footer">${btn(t('logout'),'logout',{icon:'logout',class:'btn-ghost'})}</div></div></section></main>`;
}

const actions={
 'refresh-health':()=>refresh(),'retry-verification':()=>mountHumanVerification(),'refresh-membership':()=>refresh(),
 'approve-application':uid=>reviewApplicationDialog(uid,'approved'),
 'reject-application':uid=>reviewApplicationDialog(uid,'rejected'),
 'add-member':()=>createMemberDialog(),
 'profile-photo':()=>profilePhotoDialog(),
 'remove-profile-photo':()=>confirmation(t('removeImage'),t('removePhotoHint'),()=>api('/profile/photo','DELETE',{})),
 'google-login':async()=>{try{const token=await googleToken(state.data.config.firebase,lang);await api('/auth/google','POST',{id_token:token,language:lang});state.auth=null;await refresh();}catch(error){const code=error.code;if(['auth/popup-closed-by-user','auth/cancelled-popup-request'].includes(code))return;throw new Error(code==='auth/popup-blocked'?'google_popup_blocked':code==='auth/unauthorized-domain'?'google_domain_error':error.message?.startsWith('google_')?error.message:'google_auth_failed');}},
 'calendar-month':offset=>{state.calendarMonth=moveMonth(state.calendarMonth,Number(offset));state.calendarDay=state.calendarMonth+'-01';render();},
 'calendar-day':key=>{state.calendarDay=key;state.calendarMonth=key.slice(0,7);render();},
 'calendar-today':()=>{const key=dayKey(new Date(),state.data.settings.timezone);state.calendarMonth=key.slice(0,7);state.calendarDay=key;render();},
 'copy-message':async()=>{await navigator.clipboard.writeText(modal.querySelector('#share-message').value);notify(t('messageCopied'));},
 'create-venue':()=>venueDialog(),'edit-venue':vid=>venueDialog(state.data.venues.find(v=>v.id===vid)),
 'archive-venue':vid=>confirmation(t('archive'),t('venueArchiveHint'),()=>api('/admin/venues/'+vid+'/archive','PATCH',{archived:true})),
 'restore-venue':async vid=>{await api('/admin/venues/'+vid+'/archive','PATCH',{archived:false});await refresh();notify(t('saved'));},
 'menu':()=>{state.menu=!state.menu;render();},'profile':()=>navigate('/profile'),
 'dismiss':()=>modal.close(),'reset-auth':()=>{state.auth=null;render();},
 'demo-admin':async()=>{await api('/auth/development','POST',{role:'admin'});await refresh();},
 'demo-member':async()=>{await api('/auth/development','POST',{role:'member'});await refresh();},
 'logout':async()=>{await api('/auth/logout','POST',{});state.admin=null;state.auth=null;await refresh();},
 'match-tab':value=>{state.matchTab=value;render();},
 'create-match':()=>createMatchDialog(),'duplicate':mid=>createMatchDialog(getMatch(mid)),'view-match':mid=>navigate('/matches/'+mid),
 'join':mid=>joinDialog(mid),'guest':mid=>joinDialog(mid,true),'cancel-registration':rid=>cancelDialog(rid),
 'accept':rid=>{const {m}=findRegistration(rid);showDialog(t('acceptSpot'),`<form class="form-stack"><p class="hint">${esc(m.title)} · ${money(m.price_cents)}</p>${check(t('policy',{hours:m.cancel_hours}),'policy')}${formActions('acceptSpot')}</form>`,()=>api('/registrations/'+rid+'/accept','POST',{accept_policy:true}));},
 'share':mid=>shareDialog(mid),'copy-share':async()=>{try{await navigator.clipboard.writeText(modal.querySelector('[name="share-link"]').value);notify(t('copied'));}catch{modal.querySelector('[name="share-link"]').select();notify(t('clipboard_error'));}},
 'close-match':mid=>closeMatchDialog(mid),'cancel-match':mid=>confirmation(t('cancelMatch'),t('cancelMatchHint'),()=>api('/admin/matches/'+mid+'/cancel','POST',{}),true),
 'publish':async mid=>{await api('/admin/matches/'+mid+'/publish','POST',{});await refresh();notify(t('saved'));},
 'record-payment':mid=>paymentDialog(null,mid),'member-payment':uid=>paymentDialog(uid),'report-payment':()=>reportDialog(),
 'confirm-report':rid=>confirmation(t('confirmReceived'),t('paymentHint'),()=>api('/admin/reports/'+rid,'POST',{action:'confirm'})),
 'reject-report':rid=>confirmation(t('reject'),t('pendingReport'),()=>api('/admin/reports/'+rid,'POST',{action:'reject'})),
 'reverse':lid=>showDialog(t('reverse'),`<p class="hint">${t('reverseHint')}</p><form>${field(t('reason'),'reason','',{required:true,area:true,max:300})}${formActions('reverse')}</form>`,fd=>api('/admin/ledger/'+lid+'/reverse','POST',{reason:fd.get('reason')})),
 'generate-statements':()=>confirmation(t('generate'),state.data.config.development?t('localMail'):t('statementHint'),async()=>{await api('/admin/statements/generate','POST',{month:state.statementPreview.month});state.statementPreview=null;}),
 'view-message':mid=>{const m=state.admin.outbox.find(m=>m.id===mid);showDialog(m.subject,`<p class="hint">${esc(m.recipient)} · ${t(m.status)}</p><div class="prewrap">${esc(m.body)}</div>`);},
 'own-statement':sid=>{const s=state.data.statements.find(s=>s.id===sid).snapshot;showDialog(t('statements')+' · '+s.month,`<div class="list-row"><span>${t('previousBalance')}</span><strong>${money(s.opening)}</strong></div>${s.entries.map(e=>`<div class="list-row"><div>${esc(entryLabel(e))}<p class="hint">${localeDate(e.occurred_at)}</p></div><span class="amount">${money(e.amount_cents)}</span></div>`).join('')}<div class="list-row"><strong>${t('monthEnd')}</strong><strong>${money(s.closing)}</strong></div><p class="hint">${t('currentBalance')}: ${money(state.data.account.balance)}</p>`);},
 'delete-member':uid=>deleteMemberDialog(uid),'edit-role':uid=>roleDialog(uid),'new-post':()=>newPostDialog()
};
document.addEventListener('click',async e=>{const link=e.target.closest('[data-nav]');if(link){e.preventDefault();navigate(link.dataset.nav);return;}const button=e.target.closest('[data-action]');if(!button)return;const action=actions[button.dataset.action];if(!action)return;try{button.disabled=true;await action(button.dataset.id);}catch(error){notify(t(error.message),true);}finally{if(button.isConnected)button.disabled=false;}});
document.addEventListener('change',e=>{if(e.target.matches('[data-language]')){setLanguage(e.target.value);render();}});
document.addEventListener('input',e=>{if(e.target.id==='member-search'){state.search=e.target.value;document.getElementById('member-list').innerHTML=memberList();}});
app.addEventListener('submit',async e=>{
 e.preventDefault();const form=e.target,fd=new FormData(form),p=Object.fromEntries(fd),button=e.submitter;button.disabled=true;
 try{
  if(form.id==='auth-request'){state.auth={email:p.email,...await api('/auth/request','POST',{...protectedFormData(form,p),language:lang})};render();}
  else if(form.id==='auth-verify'){await api('/auth/verify','POST',{email:state.auth.email,code:p.code});state.auth=null;await refresh();}
  else if(form.id==='membership-form'){await api('/membership/application','POST',{...protectedFormData(form,p),language:lang});await refresh();notify(t('applicationSent'));}
  else if(form.id==='profile-form'){await api('/profile','PATCH',p);setLanguage(p.language);await refresh();notify(t('saved'));}
  else if(form.id==='guest-permission-form'){await api('/admin/matches/'+form.dataset.mid+'/guests','PATCH',{allow_guests:fd.has('allow_guests')});await refresh();notify(t('saved'));}
  else if(form.id==='settings-form'){await api('/admin/settings','PATCH',{...p,price_cents:Math.round(Number(p.price)*100),capacity:Number(p.capacity),cancel_hours:Number(p.cancel_hours)});await refresh();notify(t('saved'));}
  else if(form.id==='statement-preview'){const result=await api('/admin/statements/preview','POST',{month:p.month});state.statementPreview={month:p.month,...result};render();}
 }catch(error){notify(t(error.message),true);if(['auth-request','membership-form'].includes(form.id)&&form.isConnected)mountHumanVerification();}finally{if(button.isConnected)button.disabled=false;}
});
async function boot(){try{if(state.route.startsWith('/m/'))state.publicMatch=await api('/public/match/'+state.route.split('/').at(-1));await refresh();}catch(error){app.innerHTML=`<main id="main" class="public-match">${brand()}${empty(t(error.message))}<button class="btn btn-primary" id="retry-boot">${t('confirm')}</button></main>`;document.getElementById('retry-boot').onclick=boot;}}
boot();
